insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g2_ss_v1'
from (values
('113.13.c.1.A',2,'On which holiday do Americans remember people who died while serving in the military?','["Memorial Day", "Flag Day", "Groundhog Day", "Labor Day"]'::jsonb,0,'Memorial Day honors those who died serving.','original'),
('113.13.c.1.A',2,'Which holiday celebrates a harvest feast shared by the Pilgrims and Native Americans?','["Arbor Day", "Thanksgiving", "Presidents'' Day", "Constitution Day"]'::jsonb,1,'Thanksgiving is a day of gratitude.','original'),
('113.13.c.1.B',3,'Which kind of place is a monument?','["a toy shop", "a grocery store", "a structure built to honor a person or event", "a movie theater"]'::jsonb,2,'Monuments honor history.','original'),
('113.13.c.1.B',3,'Which is a government building where a state''s laws are made?','["a bakery", "a gym", "a zoo", "the state capitol"]'::jsonb,3,'The capitol houses the legislature.','original'),
('113.13.c.2.A',3,'Who was the first African American Justice on the Supreme Court?','["Thurgood Marshall", "Theodore Roosevelt", "Sam Houston", "Irma Rangel"]'::jsonb,0,'Thurgood Marshall served on the Supreme Court.','original'),
('113.13.c.2.A',3,'Who was the first Mexican American woman elected to the Texas House?','["Eleanor Roosevelt", "Irma Rangel", "Harriet Tubman", "Betsy Ross"]'::jsonb,1,'Irma Rangel served in the Texas legislature.','original'),
('113.13.c.2.A',3,'Which President helped protect national parks and forests?','["John Tyler", "Franklin Pierce", "Theodore Roosevelt", "James Buchanan"]'::jsonb,2,'Roosevelt was a conservationist.','original'),
('113.13.c.2.B',3,'Why do people study local history?','["to avoid maps", "to stop growing", "to forget old stories", "to learn how the community changed"]'::jsonb,3,'Local history explains change.','original'),
('113.13.c.3.A',2,'Which part of a map explains what the symbols mean?','["legend", "scale of years", "title", "compass"]'::jsonb,0,'A legend (key) explains symbols.','original'),
('113.13.c.3.A',2,'Which part of a map tells what the map shows?','["legend", "title", "border", "stamp"]'::jsonb,1,'The title names the topic.','original'),
('113.13.c.3.A',2,'Which tool on a map shows north, south, east, and west?','["ruler", "weather vane", "compass rose", "clock"]'::jsonb,2,'A compass rose shows directions.','original'),
('113.13.c.3.B',3,'A student draws a map of the classroom. What should be on it?','["a joke", "a recipe", "a song", "desks, door, and window in the right places"]'::jsonb,3,'Maps show real locations.','original'),
('113.13.c.4.A',2,'How many continents are there?','["7", "3", "12", "5"]'::jsonb,0,'There are seven continents.','original'),
('113.13.c.4.A',2,'Which is the largest ocean on Earth?','["Indian Ocean", "Pacific Ocean", "Atlantic Ocean", "Arctic Ocean"]'::jsonb,1,'The Pacific is the largest.','original'),
('113.13.c.4.A',2,'Which continent do we live on in Texas?','["Europe", "Africa", "North America", "Asia"]'::jsonb,2,'Texas is in North America.','original'),
('113.13.c.4.B',3,'What is the capital of Texas?','["Dallas", "El Paso", "Houston", "Austin"]'::jsonb,3,'Austin is the capital.','original'),
('113.13.c.4.B',3,'What is the capital of the United States?','["Washington, D.C.", "New York City", "Los Angeles", "Chicago"]'::jsonb,0,'The capital is Washington, D.C.','original'),
('113.13.c.4.B',3,'Which two countries border the United States?','["Japan and China", "Canada and Mexico", "Brazil and Peru", "France and Spain"]'::jsonb,1,'Canada is north and Mexico is south.','original'),
('113.13.c.5.A',3,'Which action is a way people change the land?','["watching clouds", "counting stars", "building a road", "breathing air"]'::jsonb,2,'Roads change the land.','original'),
('113.13.c.5.A',3,'Clearing land for farming is an example of...','["a map legend", "a new continent", "a holiday", "changing the environment"]'::jsonb,3,'Farming alters the land.','original'),
('113.13.c.5.B',3,'What can happen if people cut down too many trees?','["animals may lose homes", "the moon shrinks", "more clouds appear", "the sea disappears"]'::jsonb,0,'Habitat loss is a consequence.','original'),
('113.13.c.5.C',2,'Which action helps conserve resources?','["wasting paper", "turning off lights when not needed", "littering", "leaving the water running"]'::jsonb,1,'Saving energy conserves.','original'),
('113.13.c.5.C',2,'Which is a way to replenish a resource?','["digging up all the soil", "burning more coal", "planting new trees", "throwing trash"]'::jsonb,2,'Replanting replaces trees.','original'),
('113.13.c.6.A',2,'Where does a family get money to buy goods and services?','["from drawing pictures only", "from picking leaves", "from wishing", "from work"]'::jsonb,3,'Work provides income.','original'),
('113.13.c.6.B',3,'A child gets five dollars. Which choice is saving?','["putting some away for later", "spending it all today", "giving it away secretly", "burning it"]'::jsonb,0,'Saving means keeping for later.','original'),
('113.13.c.6.B',3,'Spending all your money on a toy means you may not have it for...','["today''s weather", "something else you want later", "breathing", "your last name"]'::jsonb,1,'Spending uses money up.','original'),
('113.13.c.7.A',2,'A farmer grows apples. What is the farmer?','["a consumer", "a customer", "a producer", "a tourist"]'::jsonb,2,'Producers make goods.','original'),
('113.13.c.7.A',2,'A person buys apples to eat. What is the person?','["a producer", "a miner", "a farmer", "a consumer"]'::jsonb,3,'Consumers use goods.','original'),
('113.13.c.7.B',3,'A baker sells bread and also buys flour. What does this show?','["people can be producers and consumers", "only farmers are producers", "only kids are consumers", "bakers do nothing"]'::jsonb,0,'People play both roles.','original'),
('113.13.c.7.C',3,'Which shows the correct steps for making a wooden chair?','["lumber, chair, tree", "tree, lumber, chair", "chair, lumber, tree", "tree, chair, lumber"]'::jsonb,1,'A chair starts as a tree.','original'),
('113.13.c.7.C',3,'A plant grown in a field becomes thread and then a T-shirt. Which one is the natural resource?','["fabric", "the T-shirt", "the plant from the field", "thread"]'::jsonb,2,'The plant is the raw material.','original'),
('113.13.c.8.A',3,'What is one job of government?','["painting pictures", "singing songs", "baking cakes", "keeping people safe"]'::jsonb,3,'Governments keep order and security.','original'),
('113.13.c.8.A',3,'Which function of government helps settle disagreements?','["managing conflict", "growing flowers", "making jokes", "building toys"]'::jsonb,0,'Courts and laws manage conflict.','original'),
('113.13.c.8.B',2,'Which is a service from the government?','["toy store", "fire protection", "pizza shop", "video game"]'::jsonb,1,'Fire departments are public services.','original'),
('113.13.c.8.B',2,'Which place do taxes help pay for so everyone can use it?','["private spa", "private yacht", "library", "candy store"]'::jsonb,2,'Libraries are public.','original'),
('113.13.c.9.A',2,'What is the title of the leader of a city?','["governor", "judge", "president", "mayor"]'::jsonb,3,'Mayors lead cities.','original'),
('113.13.c.9.A',2,'Who leads a state in the United States?','["governor", "coach", "principal", "mayor"]'::jsonb,0,'Governors lead states.','original'),
('113.13.c.9.B',3,'How is a governor''s role different from a mayor''s?','["they are the same", "a governor leads a state; a mayor leads a city", "a mayor leads a country", "a governor leads a school"]'::jsonb,1,'Their areas differ.','original'),
('113.13.c.9.C',3,'Which is one way a public official gets a job?','["a spelling bee", "buying a ticket", "election", "a coin toss"]'::jsonb,2,'Voters elect officials.','original'),
('113.13.c.9.D',3,'Which is a way citizens take part in government?','["never speak", "ignore the news", "break rules", "vote when they are old enough"]'::jsonb,3,'Voting is participation.','original'),
('113.13.c.10.A',2,'Which shows truthfulness?','["telling what really happened", "blaming others", "making up stories", "hiding mistakes"]'::jsonb,0,'Truthful people are honest.','original'),
('113.13.c.10.A',2,'Which shows respect?','["grabbing toys", "listening while others talk", "calling names", "ignoring people"]'::jsonb,1,'Respect includes listening.','original'),
('113.13.c.10.B',3,'Paul Revere is remembered for...','["flying a plane", "inventing the telephone", "riding to warn colonists", "building skyscrapers"]'::jsonb,2,'He warned people during the American Revolution.','original'),
('113.13.c.10.B',3,'The Navajo Code Talkers helped the United States by...','["building bridges", "teaching art", "farming cotton", "sending secret messages in their language"]'::jsonb,3,'They used their language as an unbreakable code.','original'),
('113.13.c.10.C',2,'Which is community service?','["picking up trash in a park", "breaking a window", "skipping chores", "yelling at neighbors"]'::jsonb,0,'Service helps others.','original'),
('113.13.c.11.A',2,'Which do we say to show respect to the Texas flag?','["a lunch order", "the Pledge to the Texas Flag", "a bedtime lullaby", "a song about snacks"]'::jsonb,1,'Texans recite the Texas pledge.','original'),
('113.13.c.11.B',2,'Which song starts with "O say can you see"?','["Jingle Bells", "Row Row Row", "The Star-Spangled Banner", "America the Beautiful"]'::jsonb,2,'It is the national anthem.','original'),
('113.13.c.11.B',2,'Which patriotic song mentions "spacious skies"?','["Twinkle Twinkle", "Happy Birthday", "Old MacDonald", "America the Beautiful"]'::jsonb,3,'It describes the American landscape.','original'),
('113.13.c.11.C',2,'A class votes on a snack. Which snack wins?','["the one with the most votes", "a random shoe", "the one with the fewest votes", "the one the teacher dislikes"]'::jsonb,0,'Majority wins.','original'),
('113.13.c.11.D',3,'Which is the state bird of Texas?','["eagle", "mockingbird", "penguin", "robin"]'::jsonb,1,'Texas''s state bird is the mockingbird.','original'),
('113.13.c.11.D',3,'Which is the state flower of Texas?','["rose", "sunflower", "bluebonnet", "tulip"]'::jsonb,2,'Bluebonnets are Texas''s flower.','original'),
('113.13.c.11.D',3,'Who is Uncle Sam?','["a pirate", "a dinosaur", "a real cousin", "a symbol of the United States"]'::jsonb,3,'Uncle Sam symbolizes America.','original'),
('113.13.c.11.E',3,'Fireworks on Independence Day reflect a love of...','["freedom", "sleeping late", "rainy weather", "homework"]'::jsonb,0,'Fireworks celebrate liberty.','original'),
('113.13.c.12.A',3,'Why do many communities hold cultural celebrations?','["to hide stories", "to share traditions and heritage", "to avoid friends", "to cancel school"]'::jsonb,1,'Celebrations honor heritage.','original'),
('113.13.c.12.B',3,'One celebration has a parade with drums. Another has dances with fans. What can you compare?','["their dinner menus only", "their spelling", "how they celebrate", "their weather forecasts"]'::jsonb,2,'You compare customs.','original'),
('113.13.c.13.A',2,'How has technology changed communication?','["people can no longer talk", "nobody can listen", "letters appeared for the first time", "people can talk or text from far away"]'::jsonb,3,'Phones and computers connect people.','original'),
('113.13.c.13.A',2,'How has technology changed travel?','["planes move people across the country quickly", "people no longer travel", "people only ride horses", "roads disappeared"]'::jsonb,0,'Planes and cars are faster.','original'),
('113.13.c.13.B',3,'How do refrigerators help families meet needs?','["grow clothes", "keep food from spoiling", "build houses", "play music only"]'::jsonb,1,'They store food safely.','original'),
('113.13.c.14',3,'Which person is known for inventing a telephone?','["Clara Barton", "Betsy Ross", "Alexander Graham Bell", "Paul Revere"]'::jsonb,2,'Bell is credited with the telephone.','original'),
('113.13.c.14',3,'Which person is known for the airplane first flown at Kitty Hawk?','["Amelia Earhart", "Neil Armstrong", "Henry Ford", "the Wright brothers"]'::jsonb,3,'The Wrights flew in 1903.','original'),
('113.13.c.15.B',3,'A letter written by a soldier long ago is a...','["primary source", "rumor", "riddle", "cartoon"]'::jsonb,0,'It was written by someone who was there.','original'),
('113.13.c.15.C',2,'Which is a good way to learn about the past?','["guess", "interview an elder", "ignore old stories", "stop asking questions"]'::jsonb,1,'Interviews gather first-hand information.','original'),
('113.13.c.15.D',3,'You read a story and say, "This is mostly about a family''s move." What did you do?','["made a map", "sang a song", "identified the main idea", "planted a tree"]'::jsonb,2,'The main idea is the big point.','original'),
('113.13.c.16.A',2,'Which time period includes dinosaurs and knights?','["tomorrow", "present time", "next year", "historical times"]'::jsonb,3,'Historical means long ago.','original'),
('113.13.c.16.B',2,'Which word means something that has not happened yet?','["future", "past", "present", "history"]'::jsonb,0,'Future is later.','original'),
('113.13.c.16.C',3,'On a timeline, which event came first?','["the latest date", "the earliest date", "tomorrow", "today"]'::jsonb,1,'Earlier dates are to the left.','original'),
('113.13.c.16.D',2,'What does the word "citizen" mean?','["a food", "a type of weather", "a member of a community or country", "a kind of animal"]'::jsonb,2,'Citizens belong to a community.','original'),
('113.13.c.16.F',3,'Which tool helps organize ideas before writing about a topic?','["ruler", "stapler", "calculator", "graphic organizer"]'::jsonb,3,'Organizers arrange ideas.','original'),
('113.13.c.17.A',2,'A group wants to pick a class name. A fair way to decide is...','["vote", "shout", "argue", "walk out"]'::jsonb,0,'Voting is democratic.','original'),
('113.13.c.17.B',3,'After listing choices and thinking about good and bad points, what is the next step?','["forget the problem", "choose and carry out a solution", "blame a classmate", "erase the list"]'::jsonb,1,'Pick and use a solution.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
